BEGIN;
SELECT no_plan();
INSERT INTO auth.users(id,email,raw_app_meta_data) VALUES
 ('95200000-0000-4000-8000-000000000001','invoice-page-owner@example.test','{"_invite_provisioned":true}'),
 ('95200000-0000-4000-8000-000000000002','invoice-page-other@example.test','{"_invite_provisioned":true}'),
 ('95200000-0000-4000-8000-000000000003','invoice-page-editor@example.test','{"_invite_provisioned":true}');
CREATE TEMP TABLE i21_tenants AS SELECT 'owner'::text label,(public.provision_company_atomic('95200000-0000-4000-8000-000000000001','{"name":"Invoice page fixture","domain":"invoice-page.test","slug":"invoice-page"}')->>'id')::uuid id
 UNION ALL SELECT 'other',(public.provision_company_atomic('95200000-0000-4000-8000-000000000002','{"name":"Invoice page other","domain":"invoice-page-other.test","slug":"invoice-page-other"}')->>'id')::uuid;
UPDATE public.users SET must_change_password=false WHERE auth_user_id IN('95200000-0000-4000-8000-000000000001','95200000-0000-4000-8000-000000000002');
INSERT INTO public.roles(tenant_id,name,name_ar,name_en,is_system_role) SELECT id,'accountant','Invoice only','Invoice only',false FROM i21_tenants WHERE label='owner' ON CONFLICT DO NOTHING;
DELETE FROM public.role_permissions WHERE role_id IN(SELECT r.id FROM public.roles r JOIN i21_tenants t ON r.tenant_id=t.id WHERE t.label='owner' AND r.name='accountant');
INSERT INTO public.role_permissions(role_id,permission_id) SELECT r.id,p.id FROM public.roles r JOIN i21_tenants t ON r.tenant_id=t.id CROSS JOIN public.permissions p WHERE t.label='owner' AND r.name='accountant' AND p.module='invoices' AND p.action IN('read','create','update','export');
INSERT INTO public.users(id,auth_user_id,tenant_id,email,role,status,must_change_password,created_by) SELECT '95200000-0000-4000-8000-000000000004','95200000-0000-4000-8000-000000000003',id,'invoice-page-editor@example.test','accountant','active',false,'95200000-0000-4000-8000-000000000001' FROM i21_tenants WHERE label='owner';
INSERT INTO public.customers(id,tenant_id,customer_code,name_ar,name_en) SELECT gen_random_uuid(),t.id,'IP'||lpad(g::text,6,'0'),'طرف اختبار '||g,CASE WHEN g=1201 THEN 'Invoice party 50%_' ELSE 'Invoice party '||g END FROM i21_tenants t CROSS JOIN generate_series(1,1201)g WHERE t.label='owner';
INSERT INTO public.invoices(tenant_id,invoice_type,customer_id,issue_date,due_date,subtotal,vat_amount,total,vat_rate,created_by)
 SELECT t.id,'sales',c.id,current_date-(g%29),current_date+7,1,0.15,1.15,15,'95200000-0000-4000-8000-000000000001' FROM i21_tenants t CROSS JOIN generate_series(1,1105)g JOIN public.customers c ON c.customer_code=CASE WHEN g=1105 THEN 'IP001201' ELSE 'IP000001' END AND c.tenant_id=t.id WHERE t.label='owner';
CREATE TEMP TABLE i21_results(label text PRIMARY KEY,result jsonb);GRANT ALL ON i21_results TO authenticated;GRANT SELECT ON i21_tenants TO authenticated;
CREATE TEMP TABLE i21_input AS SELECT jsonb_build_object('invoice_type','sales','customer_id',c.id,'issue_date',current_date,'due_date',current_date,'lines','[{"item_name":"Exact item","description":"Receipt fixture","quantity":1,"unit_price":1.2345,"vat_rate":0}]'::jsonb) input FROM public.customers c JOIN i21_tenants t ON t.id=c.tenant_id WHERE t.label='owner' AND c.customer_code='IP000001';GRANT SELECT ON i21_input TO authenticated;
SELECT ok(NOT has_schema_privilege(r,'invoice_workflow_private','USAGE'),r||' cannot use private receipt schema') FROM(VALUES('anon'),('authenticated'),('service_role'))v(r);
SELECT ok(NOT has_table_privilege(r,'invoice_workflow_private.draft_receipts',p),r||' cannot '||p||' draft receipts') FROM(VALUES('anon'),('authenticated'),('service_role'))v(r) CROSS JOIN(VALUES('SELECT'),('INSERT'),('UPDATE'),('DELETE'))w(p);
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='invoice_workflow_private.draft_receipts'::regclass),'draft receipts retain RLS');
SELECT ok(has_function_privilege('authenticated',f,'EXECUTE'),'caller may execute '||f) FROM(VALUES('public.read_my_invoice_page(text,text,integer,integer,boolean)'),('public.read_my_invoice_party_page(text,text,integer,integer)'),('public.save_my_invoice_draft(jsonb,uuid,timestamptz,uuid)'))v(f);
SELECT ok(NOT has_function_privilege(r,f,'EXECUTE'),r||' cannot execute '||f) FROM(VALUES('anon'),('service_role'))v(r) CROSS JOIN(VALUES('public.read_my_invoice_page(text,text,integer,integer,boolean)'),('public.read_my_invoice_party_page(text,text,integer,integer)'),('public.save_my_invoice_draft(jsonb,uuid,timestamptz,uuid)'))w(f);
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"95200000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
SELECT is(public.user_has_permission('accounting','read'),false,'invoice-only editor has no unrelated accounting read');
SELECT is(public.user_has_permission('invoices','create'),true,'invoice-only editing permission is nonvacuous');
INSERT INTO i21_results VALUES('page',public.read_my_invoice_page()),('last',public.read_my_invoice_page('','all',23,50)),('export',public.read_my_invoice_page('','all',1,100,true)),('party',public.read_my_invoice_party_page('customers','',49,25));
SELECT is((SELECT (result->>'total')::int FROM i21_results WHERE label='page'),1105,'invoice count spans all records beyond API caps');
SELECT is((SELECT jsonb_array_length(result->'rows') FROM i21_results WHERE label='page'),50,'first page is bounded');
SELECT is((SELECT jsonb_array_length(result->'rows') FROM i21_results WHERE label='last'),5,'last page includes remaining invoices');
SELECT is((SELECT (result->'summary'->>'total')::int FROM i21_results WHERE label='last'),1105,'global total is independent of the loaded page');
SELECT is((SELECT (result->'summary'->>'drafts')::int FROM i21_results WHERE label='last'),1105,'global draft count is not a page count');
SELECT is((SELECT result->'summary'->>'value_sar' FROM i21_results WHERE label='last'),'1270.75','global currency value sums exact cents');
SELECT is((public.read_my_invoice_page('50%_')->>'total')::int,1,'percent and underscore search are literal across all parties');
SELECT is((public.read_my_invoice_page('Invoice party 1200')->>'total')::int,0,'search does not invent invoice matches from unused parties');
SELECT is((public.read_my_invoice_page('','issued')->>'total')::int,0,'status filter runs across the complete set');
SELECT is((public.read_my_invoice_page('50%_')->'summary'->>'total')::int,1105,'search does not turn global KPIs into filtered page metrics');
SELECT is((SELECT jsonb_array_length(result->'rows') FROM i21_results WHERE label='export'),1105,'export includes every matching row beyond 500 and 1000');
SELECT is((SELECT count(DISTINCT x->>'id')::int FROM i21_results r CROSS JOIN LATERAL jsonb_array_elements(r.result->'rows')x WHERE label='export'),1105,'complete export contains no duplicate IDs');
SELECT is((SELECT jsonb_agg(x->>'id' ORDER BY p,n) FROM generate_series(1,23)p CROSS JOIN LATERAL jsonb_array_elements(public.read_my_invoice_page('','all',p,50)->'rows') WITH ORDINALITY x(x,n)),(SELECT jsonb_agg(x->>'id' ORDER BY n) FROM i21_results r CROSS JOIN LATERAL jsonb_array_elements(r.result->'rows') WITH ORDINALITY x(x,n) WHERE label='export'),'stable date/id ordering makes pages equal the complete export');
SELECT is((SELECT (result->>'total')::int FROM i21_results WHERE label='party'),1201,'invoice-only party options cover more than 1000 rows');
SELECT is((SELECT result->'rows'->0->>'code' FROM i21_results WHERE label='party'),'IP001201','last party is selectable beyond the old 200-row cap');
SELECT is((public.read_my_invoice_party_page('customers','50%_')->>'total')::int,1,'party search treats wildcard characters literally');
SELECT throws_like($$SELECT public.read_my_invoice_page('','all',1,101)$$,'INV002:%','invalid page sizes are rejected');
SELECT throws_like($$SELECT public.read_my_invoice_page('','unknown')$$,'INV002:%','unknown status does not silently become all');
SELECT lives_ok($$INSERT INTO i21_results SELECT 'save',public.save_my_invoice_draft(input,NULL,NULL,'95200000-0000-4000-8000-000000000010') FROM i21_input$$,'application draft uses one real transactional receipt');
SELECT lives_ok($$INSERT INTO i21_results SELECT 'replay',public.save_my_invoice_draft(input,NULL,NULL,'95200000-0000-4000-8000-000000000010') FROM i21_input$$,'lost create response can be retried without a duplicate');
SELECT is((SELECT result->>'id' FROM i21_results WHERE label='save'),(SELECT result->>'id' FROM i21_results WHERE label='replay'),'replayed create returns the original invoice');
SELECT is((SELECT (result->>'replayed')::boolean FROM i21_results WHERE label='replay'),true,'replay is explicit');
SET LOCAL TIME ZONE 'UTC';
SELECT lives_ok($$INSERT INTO i21_results SELECT 'update_utc',public.save_my_invoice_draft(input||'{"notes":"Timezone-independent update"}',(r.result->>'id')::uuid,(r.result->>'updated_at')::timestamptz,'95200000-0000-4000-8000-000000000016') FROM i21_input CROSS JOIN i21_results r WHERE r.label='save'$$,'reviewed update records a UTC-normalized intent');
SET LOCAL TIME ZONE 'Asia/Riyadh';
SELECT lives_ok($$INSERT INTO i21_results SELECT 'update_riyadh',public.save_my_invoice_draft(input||'{"notes":"Timezone-independent update"}',(r.result->>'id')::uuid,(r.result->>'updated_at')::timestamptz,'95200000-0000-4000-8000-000000000016') FROM i21_input CROSS JOIN i21_results r WHERE r.label='save'$$,'the same reviewed instant replays across session timezones');
SELECT is((SELECT (result->>'replayed')::boolean FROM i21_results WHERE label='update_riyadh'),true,'timezone change does not turn an exact update replay into a conflict');
SET LOCAL TIME ZONE 'UTC';
SELECT throws_like($$SELECT public.save_my_invoice_draft(jsonb_set(input,'{lines,0,unit_price}','1.2346'),NULL,NULL,'95200000-0000-4000-8000-000000000010') FROM i21_input$$,'INV015:%','different intent is rejected even if rounded totals are equal');
SELECT throws_like($$SELECT public.save_my_invoice_draft(input) FROM i21_input$$,'INV002:%','application RPC requires its retry identity');
RESET ROLE;
SELECT is((SELECT count(*)::int FROM public.invoices i JOIN i21_results r ON i.id=(r.result->>'id')::uuid WHERE r.label='save'),1,'replayed create left exactly one invoice');
SELECT is((SELECT count(*)::int FROM public.audit_log a JOIN i21_results r ON a.entity_id=(r.result->>'id')::uuid WHERE r.label='save' AND a.action='invoice_draft_created'),1,'replayed create left exactly one audit');
SELECT is((SELECT count(*)::int FROM invoice_workflow_private.draft_receipts WHERE request_id='95200000-0000-4000-8000-000000000010'),1,'replayed create left exactly one immutable receipt');
SELECT throws_like($$UPDATE invoice_workflow_private.draft_receipts SET response='{}' WHERE request_id='95200000-0000-4000-8000-000000000010'$$,'INV_RECEIPT_IMMUTABLE%','even trusted code cannot rewrite committed receipt evidence');
CREATE FUNCTION pg_temp.i21_audit_fault() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.action='invoice_draft_created' THEN RAISE EXCEPTION 'synthetic invoice receipt audit fault';END IF;RETURN NEW;END$$;
CREATE TRIGGER i21_audit_fault BEFORE INSERT ON public.audit_log FOR EACH ROW EXECUTE FUNCTION pg_temp.i21_audit_fault();
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.save_my_invoice_draft(input,NULL,NULL,'95200000-0000-4000-8000-000000000011') FROM i21_input$$,'P0001','synthetic invoice receipt audit fault','failed audit aborts the draft and receipt together');
RESET ROLE;
DROP TRIGGER i21_audit_fault ON public.audit_log;
SELECT is((SELECT count(*)::int FROM invoice_workflow_private.draft_receipts WHERE request_id='95200000-0000-4000-8000-000000000011'),0,'failed audit leaves no success receipt');
SELECT is((SELECT count(*)::int FROM public.invoices WHERE tenant_id=(SELECT id FROM i21_tenants WHERE label='owner')),1106,'failed create leaves no extra invoice');
DELETE FROM public.role_permissions WHERE role_id IN(SELECT r.id FROM public.roles r JOIN i21_tenants t ON r.tenant_id=t.id WHERE t.label='owner' AND r.name='accountant') AND permission_id IN(SELECT id FROM public.permissions WHERE module='invoices' AND action='create');
SET LOCAL ROLE authenticated;
SELECT throws_like($$SELECT public.save_my_invoice_draft(input,NULL,NULL,'95200000-0000-4000-8000-000000000010') FROM i21_input$$,'AUTH007:%','revoked creation permission is checked before returning a prior receipt');
SELECT set_config('request.jwt.claims','{"sub":"95200000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
SELECT is((public.read_my_invoice_page()->>'total')::int,0,'another tenant receives no invoice rows');
SELECT is((public.read_my_invoice_party_page('customers')->>'total')::int,0,'another tenant receives no party rows');
SELECT throws_like($$SELECT public.save_my_invoice_draft(input,NULL,NULL,'95200000-0000-4000-8000-000000000010') FROM i21_input$$,'INV005:%','copied request ID cannot select a foreign party');
RESET ROLE;
INSERT INTO public.invoices(tenant_id,invoice_type,customer_id,issue_date,due_date,subtotal,vat_amount,total,vat_rate,created_by)
 SELECT t.id,'sales',c.id,current_date,current_date,1,0.15,1.15,15,'95200000-0000-4000-8000-000000000001' FROM i21_tenants t CROSS JOIN generate_series(1,10001)g JOIN public.customers c ON c.customer_code='IP000001' AND c.tenant_id=t.id WHERE t.label='owner';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"95200000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
SELECT throws_like($$SELECT public.read_my_invoice_page('','all',1,100,true)$$,'INV_EXPORT_LIMIT:%','oversized export explicitly requires narrowing instead of truncating');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
